// The 3-week ramp program I ran in production, encoded. In production, week 2 and 3 sends move to Wait nodes or dated sub-schedules.
const h = $input.first().json.body;
const plan = [
  'WEEK 1 - SHADOW: pair on live tickets with mentor, read the top 10 playbooks, sit in on one escalation, no solo queue work. Goal: vocabulary and context.',
  'WEEK 2 - SUPERVISED: own easy-queue tickets with mentor review before every send, QA sampling at 100%, daily 15-minute debrief. Goal: reps with a net.',
  'WEEK 3 - SOLO WITH WATCH: full queue access, QA sampling at 50%, graduation review Friday. Goal: earn the badge with data.',
  'GRADUATION CRITERIA (measured from the queue, not vibes): first-response median under 60m, zero QA fails in week 3, CSAT >= 4.0 on 5+ rated tickets, one playbook improved or written.'
].join('

');
return [
  { json: { to: h.email, subject: 'Welcome! Your 3-week ramp starts now', body: 'Hi ' + h.name.split(' ')[0] + ',

Welcome to support engineering. Your mentor is ' + h.mentor + '. Here is the whole 3-week plan up front, so nothing is a surprise:

' + plan + '

Ask questions early and often; the only bad question in week 1 is the one you sat on.' } },
  { json: { to: h.mentorEmail, subject: 'You are mentoring ' + h.name + ' for the next 3 weeks', body: 'Mentor packet for ' + h.name + ':

' + plan + '

Your job: review every send in week 2, be interruptible, and flag risks to the lead early. Mentoring counts in your workload plan; your queue target is reduced 30% for these 3 weeks.' } },
  { json: { to: 'it-lead@example.com', subject: '[Lead] Ramp started: ' + h.name, body: 'Track: ' + h.name + ' (mentor ' + h.mentor + ', started ' + (h.startDate || 'today') + ').

' + plan + '

Calendar: week-2 QA at 100%, week-3 at 50%, graduation review Friday of week 3.' } }
];
